    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) || 
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1) || (count > 16) || (!isfinite(efficiency)) || (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }

    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    *body_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    *mechanical_power = 0.0;
    *bus_power = 0.0;

    for (size_t i = 0; i < count; ++i) {
        if (!isfinite(wheel_torque[i])) {
            return ADCS_E_RANGE;
        }

        adcs_vec3_t axis_normalized;
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis_normalized) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // tau_body = -sum(u_i * a_i)
        adcs_vec3_t torque_term = adcs_vec3_scale(&axis_normalized, -wheel_torque[i]);
        *body_torque = adcs_vec3_add(body_torque, &torque_term);

        // P_mech = sum(u_i * omega_i)
        double mech_pwr_i = wheel_torque[i] * wheels[i].speed_rad_s;
        *mechanical_power += mech_pwr_i;

        // P_bus = sum_{u_i*omega_i>0}(u_i*omega_i/efficiency)
        if (mech_pwr_i > 0.0) {
            *bus_power += mech_pwr_i / efficiency;
        }
    }

    return ADCS_OK;
}

