    if ((count < 1U) || (count > 16U) || (!isfinite(efficiency)) || (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }

    // 3. Compute cluster momentum using the library function
    adcs_status_t stat = adcs_wheel_momentum(wheels, count, momentum);
    if (stat != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    // 4. Initialize accumulators for body torque, mechanical power, and bus power
    adcs_vec3_t tau_acc = {0.0, 0.0, 0.0};
    double p_mech_acc = 0.0;
    double p_bus_acc = 0.0;
    adcs_vec3_t axis_norm;
    size_t i;

    // 5. Iterate through each wheel to compute torque and power contributions
    for (i = 0; i < count; ++i) {
        // Check if wheel torque is finite
        if (!isfinite(wheel_torque[i])) {
            return ADCS_E_RANGE;
        }

        // Normalize the wheel axis
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis_norm) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        double u = wheel_torque[i];
        double omega = wheels[i].speed_rad_s;

        // Accumulate body torque: tau_body = -sum(u_i * a_i)
        adcs_vec3_t tau_term = adcs_vec3_scale(&axis_norm, -u);
        tau_acc = adcs_vec3_add(&tau_acc, &tau_term);

        // Accumulate mechanical power: P_mech = sum(u_i * omega_i)
        double p_mech = u * omega;
        p_mech_acc += p_mech;

        // Accumulate bus power: P_bus = sum(u_i * omega_i / efficiency) if u_i * omega_i > 0
        if (p_mech > 0.0) {
            p_bus_acc += p_mech / efficiency;
        }
    }

    // 6. Assign final results to output parameters
    *body_torque = tau_acc;
    *mechanical_power = p_mech_acc;
    *bus_power = p_bus_acc;

    return ADCS_OK;
}

